+/** The number of yuzu needed for `guests`, with two capybaras sharing one yuzu. */
+export function yuzuNeeded(guests: number): number {
+  if (!Number.isInteger(guests) || guests < 0) {
+    throw new RangeError('guests must be a non-negative integer');
+  }
+  return Math.ceil(guests / 2);
+}
