@@ -14,3 +14,11 @@ export function soakEndsAt(booking: Booking): number {
 export function isSoaking(booking: Booking, nowMinute: number): boolean {
   return nowMinute >= booking.startMinute && nowMinute < soakEndsAt(booking);
 }
+
+/** Minutes of soak remaining at `nowMinute`, never negative. */
+export function minutesLeft(booking: Booking, nowMinute: number): number {
+  if (nowMinute < booking.startMinute) {
+    return booking.durationMinutes;
+  }
+  return Math.max(0, soakEndsAt(booking) - nowMinute);
+}
